async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((response) => {
        if (!response.ok) throw new Error('Failed to load analytics');
        return response.json();
      }),
      fetch('/api/notifications').then((response) => {
        if (!response.ok) throw new Error('Failed to load notifications');
        return response.json();
      }),
      fetch('/api/settings').then((response) => {
        if (!response.ok) throw new Error('Failed to load settings');
        return response.json();
      })
    ]);

    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: { views: 1200, revenue: 5400 },
      notifications: [
        { id: 1, title: 'Welcome back', read: false },
        { id: 2, title: 'Weekly report ready', read: true }
      ],
      settings: { theme: 'light', emailNotifications: true }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>
      <section>
        <h3>Analytics</h3>
        <p>Views: {analytics.views}</p>
        <p>Revenue: {analytics.revenue}</p>
      </section>
      <section>
        <h3>Notifications</h3>
        <p>Total: {notifications.length}</p>
      </section>
      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Email notifications: {settings.emailNotifications ? 'On' : 'Off'}</p>
      </section>
    </div>
  );
}
